def compare_versions(a: str, b: str) -> int:
    def parse_version(v: str):
        # Remove build metadata (everything after +)
        v = v.split('+')[0]

        # Split into core version and pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = v
            prerelease_parts = None

        # Parse core version
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        return major, minor, patch, prerelease_parts

    def is_numeric(s: str) -> bool:
        return s.isdigit()

    def compare_prerelease(pre_a, pre_b):
        # If both are None, versions are equal
        if pre_a is None and pre_b is None:
            return 0
        # Version without pre-release has higher precedence
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        # Compare pre-release identifiers one by one
        for i in range(max(len(pre_a), len(pre_b))):
            # More identifiers is higher precedence
            if i >= len(pre_a):
                return -1
            if i >= len(pre_b):
                return 1

            id_a = pre_a[i]
            id_b = pre_b[i]

            num_a = is_numeric(id_a)
            num_b = is_numeric(id_b)

            # Both numeric: compare numerically
            if num_a and num_b:
                if int(id_a) < int(id_b):
                    return -1
                elif int(id_a) > int(id_b):
                    return 1
            # One numeric, one not: numeric has lower precedence
            elif num_a and not num_b:
                return -1
            elif not num_a and num_b:
                return 1
            # Both non-numeric: ASCII order
            else:
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1

        return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare core version
    if major_a != major_b:
        return -1 if major_a < major_b else 1
    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1
    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    # Compare pre-release
    return compare_prerelease(pre_a, pre_b)
